# Source for the question bank. Run `python3 tools/build_content.py` after editing.
# Each entry: topic, stem, choices, answer (index of the correct choice),
# explanation, card = (cloze text using {{...}}, concise extra shown after reveal).

def q(topic, stem, choices, answer, explanation, card):
    return dict(topic=topic, stem=stem, choices=choices, answer=answer,
                explanation=explanation, card=dict(text=card[0], extra=card[1]))

